-- 按日、按玩家汇总在线分钟；无时长上报单列，保留在活跃分母；档位包含空档。
SELECT day "数据日期",b.bucket_name "在线时长区间",count(DISTINCT CASE WHEN p.bucket_order=b.bucket_order THEN pid END) "人数",count(DISTINCT pid) "当日活跃人数",cast(round(1.000000*count(DISTINCT CASE WHEN p.bucket_order=b.bucket_order THEN pid END)/nullif(count(DISTINCT pid),0),4) AS decimal(18,4)) "人数占比",round(sum(CASE WHEN p.bucket_order=b.bucket_order THEN minutes ELSE 0 END),2) "在线总分钟" FROM (SELECT a.*,CASE WHEN duration_records=0 THEN 0 WHEN minutes<1 THEN 1 WHEN minutes<2 THEN 2 WHEN minutes<3 THEN 3 WHEN minutes<4 THEN 4 WHEN minutes<5 THEN 5 WHEN minutes<6 THEN 6 WHEN minutes<11 THEN 7 WHEN minutes<16 THEN 8 WHEN minutes<31 THEN 9 WHEN minutes<61 THEN 10 WHEN minutes<121 THEN 11 WHEN minutes<241 THEN 12 WHEN minutes<361 THEN 13 ELSE 14 END bucket_order FROM (SELECT e."$part_date" day, u.pid, u.reg_day, u.channel_id, count_if(e."$part_event"='ad_log') ads, count_if(e."$part_event"='ad_log' AND e.result='1') ads_ok, sum(CASE WHEN e."$part_event"='ta_mg_hide' THEN coalesce(e."#duration",0) ELSE 0 END)/60.0 minutes, count_if(e."$part_event"='ta_mg_hide' AND e."#duration" IS NOT NULL) duration_records, count_if(e."$part_event"='battle_start') starts FROM ta.v_event_54 e JOIN (SELECT "#user_id",pid,reg_day,channel_id FROM (SELECT r.*,cast(reg_day AS varchar) "$part_date" FROM (SELECT "#user_id", coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)) pid, date(min(first_login_time) OVER(PARTITION BY coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)))) reg_day, coalesce(first_value(channel_id) OVER(PARTITION BY coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)) ORDER BY first_login_time NULLS LAST),'未知') channel_id FROM ta.v_user_54 WHERE domain='release' AND game_name='yishuajiushangtou') r) registered WHERE ${PartDate:date2} AND ${Selector:selector3}) u ON e."#user_id"=u."#user_id" WHERE e.game_name='yishuajiushangtou' AND ${PartDate:date1} GROUP BY 1,2,3,4) a WHERE ${Selector:selector4}) p CROSS JOIN (VALUES (0)) s(scope) CROSS JOIN (VALUES (0,'无时长记录'),(1,'0–<1分钟'),(2,'1–<2分钟'),(3,'2–<3分钟'),(4,'3–<4分钟'),(5,'4–<5分钟'),(6,'5–<6分钟'),(7,'6–<11分钟'),(8,'11–<16分钟'),(9,'16–<31分钟'),(10,'31–<61分钟'),(11,'61–<121分钟'),(12,'121–<241分钟'),(13,'241–<361分钟'),(14,'≥361分钟')) b(bucket_order,bucket_name) GROUP BY day,CASE WHEN s.scope=0 THEN '全部渠道' ELSE channel_id END,b.bucket_order,b.bucket_name ORDER BY 1 DESC,b.bucket_order